  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum Role {\n  USER\n  DOCTOR\n  AGRONOMIST\n  ADMIN\n}\n\nenum DangerLevel {\n  deadly\n  mild\n  harmless\n}\n\nenum VenomCategory {\n  neurotoxic\n  hemotoxic\n  cytotoxic\n  myotoxic\n  non_venomous\n}\n\nenum PestCategory {\n  crop_pest\n  stinging_insect\n}\n\nenum PestSeverity {\n  critical\n  moderate\n  low\n}\n\nenum TreatmentType {\n  organic\n  chemical\n}\n\n// ----------------------------------------------------\n// 1. User & Authentication\n// ----------------------------------------------------\nmodel User {\n  id              String           @id @default(uuid())\n  email           String           @unique\n  passwordHash    String\n  name            String\n  phone           String?\n  role            Role             @default(USER)\n  identifications Identification[]\n  emergencyCalls  EmergencyLog[]\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  @@map(\"users\")\n}\n\n// ----------------------------------------------------\n// 2. Snake & Antivenom Domain\n// ----------------------------------------------------\nmodel Snake {\n  id                   String           @id\n  scientificName       String           @unique\n  family               String\n  commonNames          Json // { \"en\": \"...\", \"bn\": \"...\", \"hi\": \"...\", ... }\n  isVenomous           Boolean\n  dangerLevel          DangerLevel\n  venomCategory        VenomCategory\n  antivenomRequired    Boolean\n  antivenomType        String?\n  commercialBrands     String[]\n  targetToxins         String[]\n  lethalityRisk        String\n  habitat              String\n  distribution         String[]\n  imageUrl             String\n  firstAidSteps        String[]\n  mythsDebunked        String[]\n  ecologicalImportance String\n  identifications      Identification[]\n  createdAt            DateTime         @default(now())\n  updatedAt            DateTime         @updatedAt\n\n  @@map(\"snakes\")\n}\n\n// ----------------------------------------------------\n// 3. Agricultural Pest & Treatment Domain\n// ----------------------------------------------------\nmodel Pest {\n  id                 String           @id\n  scientificName     String           @unique\n  commonNames        Json // { \"en\": \"...\", \"bn\": \"...\", ... }\n  category           PestCategory     @default(crop_pest)\n  affectedCrops      String[] // ['mango', 'litchi', 'rice']\n  severity           PestSeverity\n  symptoms           String[]\n  damageMechanism    String\n  yieldLossPotential String\n  stingRemedy        String?\n  imageUrl           String\n  treatments         Treatment[]\n  identifications    Identification[]\n  createdAt          DateTime         @default(now())\n  updatedAt          DateTime         @updatedAt\n\n  @@map(\"pests\")\n}\n\nmodel Treatment {\n  id                     String        @id @default(uuid())\n  pestId                 String\n  pest                   Pest          @relation(fields: [pestId], references: [id], onDelete: Cascade)\n  type                   TreatmentType\n  title                  String\n  activeIngredient       String\n  dosagePerLiter         Float\n  dosageUnit             String // 'ml' or 'g'\n  commercialExamples     String[]\n  optimalTiming          String\n  preHarvestIntervalDays Int           @default(0)\n  safetyInstructions     String\n  createdAt              DateTime      @default(now())\n  updatedAt              DateTime      @updatedAt\n\n  @@map(\"treatments\")\n}\n\n// ----------------------------------------------------\n// 4. Hospitals & Antivenom Centers\n// ----------------------------------------------------\nmodel Hospital {\n  id                String         @id\n  name              String\n  country           String         @default(\"BD\")\n  district          String\n  division          String\n  hotline           String\n  hasAntivenomStock Boolean        @default(true)\n  address           String\n  latitude          Float\n  longitude         Float\n  emergencyUnit     String?\n  icuAvailable      Boolean        @default(true)\n  emergencyLogs     EmergencyLog[]\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  @@map(\"hospitals\")\n}\n\n// ----------------------------------------------------\n// 5. Identification & Diagnostic Logs\n// ----------------------------------------------------\nmodel Identification {\n  id          String   @id @default(uuid())\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id])\n  type        String // 'snake' | 'pest'\n  imageUrl    String\n  userRegion  String?\n  cropType    String?\n  confidence  Float\n  rawAiOutput Json\n  snakeId     String?\n  snake       Snake?   @relation(fields: [snakeId], references: [id])\n  pestId      String?\n  pest        Pest?    @relation(fields: [pestId], references: [id])\n  isCorrect   Boolean? // User feedback\n  createdAt   DateTime @default(now())\n\n  @@map(\"identifications\")\n}\n\n// ----------------------------------------------------\n// 6. Emergency Call & SOS Dispatch Log\n// ----------------------------------------------------\nmodel EmergencyLog {\n  id          String    @id @default(uuid())\n  userId      String?\n  user        User?     @relation(fields: [userId], references: [id])\n  hospitalId  String?\n  hospital    Hospital? @relation(fields: [hospitalId], references: [id])\n  callerPhone String?\n  latitude    Float?\n  longitude   Float?\n  notes       String?\n  createdAt   DateTime  @default(now())\n\n  @@map(\"emergency_logs\")\n}\n",
